insert into public.products (id, slug, category_id, name, technical_name, short, description, composition, highlights, claims, removable_cover, reversible, summer_winter, hybrid, firmness_display, line_code, status, sort, lead_time, match, bundle_family) values ('4e3ab029-d797-558f-8017-b4b2566294f0', 'eco', '9cd67f1e-437e-55f2-a4f8-4ebf83864bd7', 'Vesuvio Eco', 'Poliuretano espanso', 'Poliuretano espanso ad alta densità: sostegno uniforme e stabile, in tre altezze.', 'L''anima monoblocco in poliuretano ad alta densità e alta portanza dà un sostegno uniforme, stabile e duraturo. È il modello più essenziale della gamma, disponibile in H20, H25 e H30. Il rivestimento non è sfoderabile.', 'Anima monoblocco in poliuretano ad alta densità e alta portanza.', '["Anima monoblocco ad alta densità", "Tre altezze: H20, H25, H30", "Sostegno uniforme"]'::jsonb, '["antiacaro", "ipoallergenico", "Free Humidity"]'::jsonb, false, false, false, false, 'Medio-rigido', 'ESS', 'published', 1, 'Produzione in circa 2 giorni prima della spedizione', '{"tech": "foam", "welcome": 0, "ventilation": false, "independent_springs": false}'::jsonb, 'foam') on conflict (id) do nothing;
insert into public.product_private (product_id, internal_notes) values ('4e3ab029-d797-558f-8017-b4b2566294f0', 'Rinominato da "Vesuvio Essential Foam" il 16/11/2026 su indicazione dell''azienda. Il vecchio indirizzo /materassi/essential-foam/ reindirizza qui. Da verificare: il nome "Eco" e'' una denominazione commerciale, sul sito non e'' accompagnato da alcuna dichiarazione ambientale perche'' non ne abbiamo di documentate.') on conflict (product_id) do nothing;
insert into public.products (id, slug, category_id, name, technical_name, short, description, composition, highlights, claims, removable_cover, reversible, summer_winter, hybrid, firmness_display, line_code, status, sort, lead_time, match, bundle_family) values ('71f76b5b-1cdd-5adb-baa5-614ec6ad9552', 'memory-duo', '9cd67f1e-437e-55f2-a4f8-4ebf83864bd7', 'Vesuvio Memory Duo', 'Memory Foam 2 strati', 'Memory Foam su base in poliuretano ad alta densità. Sfoderabile e reversibile.', 'Uno strato di comfort in Memory Foam poggia su una base portante in poliuretano ad alta densità. È più accogliente dell''Eco ed è reversibile: un lato invernale in Memory e un lato più fresco per l''estate. Il rivestimento è sfoderabile.', 'Memory Foam premium ad alta densità + base di supporto in poliuretano ad alta densità.', '["Memory Foam 2 strati", "Lato invernale e lato estivo", "Sfoderabile"]'::jsonb, '["antiacaro", "ipoallergenico", "Free Humidity"]'::jsonb, true, true, true, false, 'Medio-rigido e accogliente', 'MD', 'published', 3, 'Produzione in circa 2 giorni prima della spedizione', '{"tech": "memory", "welcome": 2, "ventilation": false, "independent_springs": false}'::jsonb, 'foam') on conflict (id) do nothing;
insert into public.product_private (product_id, internal_notes) values ('71f76b5b-1cdd-5adb-baa5-614ec6ad9552', 'H30 indicata dall''azienda la sera del 16/11/2026. Un solo valore corretto su autorizzazione: il 160x190 in H30 era scritto 329 euro, unico prezzo dei materassi non multiplo di 10, tra un 290 e un 340: portato a 330. Da ricontrollare al prossimo listino.') on conflict (product_id) do nothing;
insert into public.products (id, slug, category_id, name, technical_name, short, description, composition, highlights, claims, removable_cover, reversible, summer_winter, hybrid, firmness_display, line_code, status, sort, lead_time, match, bundle_family) values ('27b81c88-21b7-5d06-b2c3-a250d43768a5', 'memory-duo-classic', '9cd67f1e-437e-55f2-a4f8-4ebf83864bd7', 'Vesuvio Memory Duo Classic', 'Memory Foam 2 strati', 'La costruzione del Memory Duo, con il rivestimento fisso.', 'Stessa costruzione del Vesuvio Memory Duo: uno strato di comfort in Memory Foam su una base portante in poliuretano ad alta densità. Qui il rivestimento è fisso, non sfoderabile, ed è diverso da quello del Memory Duo: lo vedi nelle foto.', 'Memory Foam premium ad alta densità + base di supporto in poliuretano ad alta densità.', '["Memory Foam 2 strati", "Rivestimento fisso"]'::jsonb, '[]'::jsonb, false, null, null, false, null, 'MDC', 'published', 2, 'Produzione in circa 2 giorni prima della spedizione', '{"tech": "memory", "welcome": 2, "ventilation": false, "independent_springs": false}'::jsonb, 'foam') on conflict (id) do nothing;
insert into public.product_private (product_id, internal_notes) values ('27b81c88-21b7-5d06-b2c3-a250d43768a5', 'Aggiunto il 16/11/2026 su indicazione dell''azienda. Foto consegnate la sera del 16/11/2026: il tessuto porta la scritta "Bamboo", che la scheda non riprende perche'' non e'' una caratteristica verificata. DA CONFERMARE: che sia il tessuto di questo modello. Prezzi: Memory Duo sfoderabile meno 20 euro per ogni misura, confermati dall''azienda la sera del 16/11/2026 rimandando indietro il listino. Da confermare: se è reversibile estate/inverno come lo sfoderabile e quali claim valgono per questo tessuto.') on conflict (product_id) do nothing;
insert into public.products (id, slug, category_id, name, technical_name, short, description, composition, highlights, claims, removable_cover, reversible, summer_winter, hybrid, firmness_display, line_code, status, sort, lead_time, match, bundle_family) values ('0eedacdc-4815-5c09-b7d4-2cce6820b44d', 'pocket-3000-elite', '9cd67f1e-437e-55f2-a4f8-4ebf83864bd7', 'Vesuvio Pocket 3000 Elite', '3000 molle insacchettate + Memory', '3000 molle insacchettate e Memory Foam: il nostro Hybrid più sostenuto.', 'Molle indipendenti insacchettate, uno strato di comfort in Memory Foam ed elementi in poliuretano ad alta densità per stabilizzazione e supporto. Pensato per chi cerca più sostegno e per chi dorme in due. Rivestimento sfoderabile.', '3000 molle insacchettate, Memory Foam ed elementi in poliuretano ad alta densità.', '["3000 molle insacchettate", "Strato di comfort in Memory", "Sfoderabile"]'::jsonb, '["antiacaro", "ipoallergenico", "Free Humidity"]'::jsonb, true, false, false, true, 'Sostenuto / medio-rigido', 'P3000', 'published', 6, 'Produzione in circa 2 giorni prima della spedizione', '{"tech": "molle", "welcome": 1, "ventilation": false, "independent_springs": true}'::jsonb, 'pocket') on conflict (id) do nothing;
insert into public.product_private (product_id, internal_notes) values ('0eedacdc-4815-5c09-b7d4-2cce6820b44d', 'Storico del nome: "Pocket 2400 Elite" fino al 15/11/2026, "Pocket 2600 Elite" fino al 16/11/2026, poi "Pocket 3000 Elite" su indicazione dell''azienda. DA VERIFICARE PRIMA DEL LANCIO: il numero di molle pubblicato e a quale misura si riferisce; le foto in scheda sono quelle scattate il 15/11/2026. Prezzi H25 del 16/11/2026: ricostruiti in proporzione dal listino portando il 160x190 a 620 euro (fattore 1,1273) e CONFERMATI dall''azienda la sera del 16/11 rimandando indietro il listino. H30 indicata dall''azienda la sera del 16/11.') on conflict (product_id) do nothing;
insert into public.products (id, slug, category_id, name, technical_name, short, description, composition, highlights, claims, removable_cover, reversible, summer_winter, hybrid, firmness_display, line_code, status, sort, lead_time, match, bundle_family) values ('b0919e50-0d2d-5c21-ab4e-c06ecb1c8735', 'pocket-1600', '9cd67f1e-437e-55f2-a4f8-4ebf83864bd7', 'Vesuvio Pocket 1600', '1600 molle insacchettate', '1600 molle insacchettate, alto 25 cm: l''ingresso nella gamma a molle.', 'Materasso a molle indipendenti insacchettate alto 25 cm, prodotto nella nostra fabbrica di Casoria. È il modello a molle più essenziale della gamma: stesso principio del Pocket 3000 Elite, con un numero di molle inferiore.', 'Molle insacchettate.', '["1600 molle insacchettate", "Altezza 25 cm"]'::jsonb, '[]'::jsonb, null, null, null, false, null, 'P1600', 'published', 5, 'Produzione in circa 2 giorni prima della spedizione', '{"tech": "molle", "welcome": 1, "ventilation": false, "independent_springs": true}'::jsonb, 'pocket') on conflict (id) do nothing;
insert into public.product_private (product_id, internal_notes) values ('b0919e50-0d2d-5c21-ab4e-c06ecb1c8735', 'Rientrato in catalogo il 16/11/2026 (era archiviato dalla mattina dello stesso giorno). Prezzi H25 del 16/11/2026: ricostruiti in proporzione dal listino portando il 160x190 a 500 euro (fattore 1,1111) e CONFERMATI dall''azienda la sera del 16/11. H30 indicata la stessa sera. Un solo valore corretto su autorizzazione: in H30 il 160x190 era scritto 540 euro, piu del 160x200 e del 165x190 (530), cioe il prezzo scendeva al crescere della misura. Portato a 520, cioe H25 (500) piu 20 euro, lo scarto H25->H30 di 9 misure su 13 di questo modello: ristabilisce anche l''ordine 520 < 530 = 530, come in H25 (500 < 510 = 510). Da ricontrollare al prossimo listino. DA VERIFICARE PRIMA DEL LANCIO: il numero di molle pubblicato e la composizione di dettaglio. Foto consegnate la sera del 16/11/2026: il tessuto porta la scritta "Antibatterico", che la scheda non riprende perche'' non e'' una caratteristica verificata. DA CONFERMARE: che sia il tessuto di questo modello.') on conflict (product_id) do nothing;
insert into public.products (id, slug, category_id, name, technical_name, short, description, composition, highlights, claims, removable_cover, reversible, summer_winter, hybrid, firmness_display, line_code, status, sort, lead_time, match, bundle_family) values ('7e3a44cc-14d7-5af3-b0dd-21efdf0a9f3c', 'memory-trio', '9cd67f1e-437e-55f2-a4f8-4ebf83864bd7', 'Vesuvio Memory Trio', 'Memory Foam 3 strati', 'Tre strati di Memory Foam, alto 27 cm: il più accogliente della gamma in schiuma.', 'Tre strati di Memory Foam per un totale di 27 cm di altezza, prodotto nella nostra fabbrica di Casoria. Dove il Memory Duo ha un solo strato di comfort sopra la base, qui gli strati sono tre: l''accoglienza è più progressiva e il materasso è più alto.', 'Memory Foam, 3 strati.', '["Memory Foam a 3 strati", "Altezza 27 cm"]'::jsonb, '[]'::jsonb, null, null, null, false, null, 'MF3', 'published', 4, 'Produzione in circa 2 giorni prima della spedizione', '{"tech": "memory", "welcome": 1.5, "ventilation": false, "independent_springs": false}'::jsonb, 'foam') on conflict (id) do nothing;
insert into public.product_private (product_id, internal_notes) values ('7e3a44cc-14d7-5af3-b0dd-21efdf0a9f3c', 'Rinominato da "Memory Foam 3 strati" (nome di listino) a "Vesuvio Memory Trio" il 16/11/2026: il nome richiama il Memory Duo e dichiara i tre strati. Il vecchio indirizzo reindirizza qui. DA VERIFICARE PRIMA DEL LANCIO: la composizione di dettaglio dei tre strati e se è sfoderabile. Foto consegnate la sera del 16/11/2026: il tessuto porta la scritta "Grafeno", ripetuta sul piano. L''immagine era marcata "non associare ad alcun prodotto" nel MEDIA_MANIFEST del 15/11, con riserva "fino a istruzioni successive": l''azienda le ha assegnate a questo modello la sera del 16/11. La scheda non riprende la scritta, perche'' il grafene non e'' una caratteristica verificata. DA CONFERMARE: che sia il tessuto di questo modello.') on conflict (product_id) do nothing;
insert into public.products (id, slug, category_id, name, technical_name, short, description, composition, highlights, claims, removable_cover, reversible, summer_winter, hybrid, firmness_display, line_code, status, sort, lead_time, match, bundle_family) values ('df39f46d-9932-5856-ab3a-43855690494c', 'memory-air-3d', '9cd67f1e-437e-55f2-a4f8-4ebf83864bd7', 'Vesuvio Memory Air 3D', 'Memory + fascia 3D', 'Memory Foam e poliuretano ad alta densità con fascia perimetrale 3D traspirante.', 'Memory Foam e poliuretano ad alta densità, con una fascia perimetrale 3D traspirante che favorisce la ventilazione laterale. Reversibile con lato invernale e lato estivo, rivestimento sfoderabile.', 'Memory Foam premium + poliuretano ad alta densità + fascia perimetrale 3D traspirante.', '["Fascia perimetrale 3D traspirante", "Lato invernale e lato estivo", "Sfoderabile"]'::jsonb, '["antiacaro", "ipoallergenico", "Free Humidity", "fascia 3D traspirante"]'::jsonb, true, true, true, false, 'Medio-rigido', 'MA3D', 'archived', 6, null, '{"tech": "memory", "welcome": 1.5, "ventilation": true, "independent_springs": false}'::jsonb, 'foam') on conflict (id) do nothing;
