insert into public.bundles (id, slug, name, tagline, description, badge, theme, sizes, default_size, status, sort) values ('734b3556-03ae-5d6a-a771-4812d31353bc', 'letto-trio', 'Letto Trio', 'Tre strati di Memory Foam, 27 cm, sulla rete a doghe della stessa misura.', 'Il Memory Trio con la Rete Flex, nella stessa misura. Il più alto della gamma in schiuma.', '27 cm di Memory Foam', 'classic', null, '160x190', 'published', 5) on conflict (id) do nothing;
insert into public.bundles (id, slug, name, tagline, description, badge, theme, sizes, default_size, status, sort) values ('3c2acc74-a439-5c34-a85b-b7e64af5fd21', 'letto-memory', 'Letto Memory', 'Memory Foam con rivestimento sfoderabile, sulla rete a doghe della stessa misura.', 'Il Memory Duo con la Rete Flex, nella stessa misura. Si aggiunge il topper se si vuole un piano ancora più accogliente.', 'Sfoderabile', 'classic', null, '160x190', 'published', 6) on conflict (id) do nothing;
insert into public.bundles (id, slug, name, tagline, description, badge, theme, sizes, default_size, status, sort) values ('c77837ef-4bb2-5842-9f74-89b48bf99689', 'singolo-completo', 'Singolo completo', 'Materasso e rete per un letto singolo: cameretta, ospiti, seconda casa.', 'Il Vesuvio Eco alto 20 cm con la Rete Flex, nelle misure da una piazza. Si può scegliere anche un''altra altezza.', 'Letto singolo', 'start', array['80x190', '80x200', '90x190', '90x200']::text[], '80x190', 'published', 7) on conflict (id) do nothing;
